'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import type { ProviderId, SignedInDevice } from './data';
import { DeviceList } from './devices';
import {
  CONNECT_MS,
  connectedCountOf,
  INITIAL,
  LOOP_AFTER_MS,
  otherDevicesOf,
  reducer,
  RESTING,
  SCRIPT,
  VERIFY_MS,
  type SecurityState,
} from './session';
import { SettingsFrame, SettingsSection } from './settings-frame';
import { SignInWays } from './sign-in-ways';
import { TwoStepCard } from './two-step';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function waysLineOf(state: SecurityState) {
  const count = connectedCountOf(state);
  if (count === 0) {
    return 'No account signs you in: you sign in with a link sent by email';
  }
  if (count > 1) {
    return `${count} accounts can sign you in`;
  }
  const only = state.providers.find(
    (provider) => provider.status === 'connected'
  );
  return `Only ${only?.name} signs you in. Connect a second account so losing one never locks you out`;
}

/** A device signed out takes its button with it: the focus goes to the next device, or to the list. */
function focusAfterSignOutOf(devices: SignedInDevice[], id: string) {
  const others = devices.filter((device) => !device.isThisDevice);
  const index = others.findIndex((device) => device.id === id);
  const neighbour = others[index + 1] ?? others[index - 1];
  if (neighbour) {
    return `[data-sign-out="${neighbour.id}"]`;
  }
  return '[data-devices]';
}

export default function Settings05() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const otherCount = otherDevicesOf(state).length;
  const hasOthers = otherCount > 0;
  const showsSignOutAll = hasOthers && !state.isConfirmingAll;
  const waysLine = waysLineOf(state);
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function connect(id: ProviderId) {
    act({ type: 'connectStarted', id });
    schedule(() => act({ type: 'connected', id }), CONNECT_MS);
  }

  function disconnect(id: ProviderId) {
    const after = reducer(state, { type: 'disconnectAsked', id });
    act({ type: 'disconnectAsked', id });
    if (after.confirmingId === id) {
      focusLater(`[data-keep="${id}"]`);
    }
  }

  function confirmDisconnect(id: ProviderId) {
    act({ type: 'disconnectConfirmed', id });
    focusLater(`[data-provider-action="${id}"]`);
  }

  function keep() {
    const id = state.confirmingId;
    act({ type: 'disconnectCancelled' });
    if (id) {
      focusLater(`[data-provider-action="${id}"]`);
    }
  }

  function signOut(id: string) {
    const target = focusAfterSignOutOf(state.devices, id);
    act({ type: 'signedOut', id });
    focusLater(target);
  }

  function askSignOutAll() {
    act({ type: 'signOutAllAsked' });
    focusLater('[data-sign-out-cancel]');
  }

  function cancelSignOutAll() {
    act({ type: 'signOutAllCancelled' });
    focusLater('[data-sign-out-all]');
  }

  function confirmSignOutAll() {
    act({ type: 'signOutAllConfirmed' });
    focusLater('[data-devices]');
  }

  function switchTwoStep(isOn: boolean) {
    const wasAsking = state.twoStep === 'confirmingOff';
    act({ type: 'twoStepSwitched', isOn });
    if (wasAsking) {
      focusLater('[data-two-step]');
    }
  }

  function changeCode(code: string) {
    act({ type: 'codeTyped', value: code });
  }

  function finishVerify() {
    act({ type: 'verified' });
    focusLater('[data-two-step]');
  }

  function verify() {
    const after = reducer(state, { type: 'verifyPressed' });
    act({ type: 'verifyPressed' });
    if (after.twoStep === 'verifying') {
      schedule(finishVerify, VERIFY_MS);
    }
  }

  function turnOff() {
    act({ type: 'turnOffConfirmed' });
    focusLater('[data-two-step]');
  }

  /** A link or a check on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  const signOutAllButton = showsSignOutAll && (
    <Button
      type='button'
      variant='outline'
      size='sm'
      data-sign-out-all
      onClick={askSignOutAll}
      className={pressedQuietOf(pressed === 'sign-out-all')}
    >
      Sign out all others
    </Button>
  );

  return (
    <ClockGate isActive={isInView}>
      <SettingsFrame
        ref={ref}
        title='Security'
        line='How you sign in to Tidewell Studio, where you are signed in, and the second step that guards your account.'
        aside={
          <ReplayButton isShown={canReplay} onReplay={replay} label='Replay' />
        }
      >
        <SettingsSection
          title='Ways to sign in'
          line={<Swap swapKey={waysLine}>{waysLine}</Swap>}
        >
          <SignInWays
            state={state}
            pressed={pressed}
            onConnect={connect}
            onDisconnect={disconnect}
            onConfirmDisconnect={confirmDisconnect}
            onKeep={keep}
          />
        </SettingsSection>
        <SettingsSection
          title='Signed-in devices'
          line='Sign out of any device you do not recognise. Places are approximate'
          action={signOutAllButton}
        >
          <DeviceList
            devices={state.devices}
            otherCount={otherCount}
            isConfirmingAll={state.isConfirmingAll}
            pressed={pressed}
            onSignOut={signOut}
            onCancelAll={cancelSignOutAll}
            onConfirmAll={confirmSignOutAll}
          />
        </SettingsSection>
        <SettingsSection
          title='Two-step verification'
          line='A code from your phone on top of your sign-in'
        >
          <TwoStepCard
            state={state}
            pressed={pressed}
            onSwitch={switchTwoStep}
            onCodeChange={changeCode}
            onVerify={verify}
            onTurnOff={turnOff}
          />
        </SettingsSection>
        <LiveRegion message={message} />
      </SettingsFrame>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';

import { EMAIL, type Provider, type ProviderId } from './data';
import type { SecurityState } from './session';
import { SURFACE } from './settings-frame';

const SPINNER_IN = {
  initial: { opacity: 0, scale: 0.6 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.6 },
};

const SPINNER_FADE = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0 },
};

function spinnerMotionOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return SPINNER_FADE;
  }
  return SPINNER_IN;
}

function statusLineOf(provider: Provider) {
  if (provider.status === 'connected') {
    return `Signed in as ${provider.account} since ${provider.connectedSince}`;
  }
  if (provider.status === 'connecting') {
    return `Waiting for ${provider.name} to send you back`;
  }
  return 'Not connected';
}

function actionLabelOf(provider: Provider) {
  if (provider.status === 'connected') {
    return 'Disconnect';
  }
  if (provider.status === 'connecting') {
    return 'Connecting';
  }
  return 'Connect';
}

function pressKeyOf(provider: Provider) {
  if (provider.status === 'connected') {
    return `disconnect-${provider.id}`;
  }
  return `connect-${provider.id}`;
}

type ProviderActionProps = {
  provider: Provider;
  isPressed: boolean;
  onPress: (provider: Provider) => void;
};

/**
 * One button for the whole life of the link, so the focus stays on it from Connect to
 * Connecting to Disconnect and back.
 */
function ProviderAction({ provider, isPressed, onPress }: ProviderActionProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const spinnerMotion = spinnerMotionOf(shouldReduceMotion);
  const label = actionLabelOf(provider);
  const isConnecting = provider.status === 'connecting';

  return (
    <Button
      type='button'
      size='sm'
      variant='outline'
      data-provider-action={provider.id}
      disabled={isConnecting}
      focusableWhenDisabled
      onClick={() => onPress(provider)}
      className={cn('data-disabled:opacity-100', pressedQuietOf(isPressed))}
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-1.5'
      >
        <AnimatePresence mode='popLayout' initial={false}>
          {isConnecting && (
            <motion.span key='spinner' className='flex' {...spinnerMotion}>
              <LoaderCircleIcon className='animate-spin' />
            </motion.span>
          )}
        </AnimatePresence>
        <Swap swapKey={label}>{label}</Swap>
      </AnimatedSize>
    </Button>
  );
}

type LastWayConfirmProps = {
  provider: Provider;
  pressed: string | null;
  onKeep: () => void;
  onConfirm: (id: ProviderId) => void;
};

function LastWayConfirm({
  provider,
  pressed,
  onKeep,
  onConfirm,
}: LastWayConfirmProps) {
  function keepOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onKeep();
  }

  return (
    <div
      role='group'
      aria-label={`Disconnect ${provider.name}`}
      onKeyDown={keepOnEscape}
      className='bg-warning/10 mx-4 mb-3 flex flex-col gap-3 rounded-lg p-3'
    >
      <p className='text-[13px] text-pretty'>
        <span className='font-medium'>{`${provider.name} is your only way to sign in.`}</span>{' '}
        {`Disconnect it and you sign in with a link sent to ${EMAIL} instead.`}
      </p>
      <div className='flex flex-wrap justify-end gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-keep={provider.id}
          onClick={onKeep}
          className={pressedQuietOf(pressed === `keep-${provider.id}`)}
        >
          {`Keep ${provider.name}`}
        </Button>
        <Button
          type='button'
          variant='destructive'
          size='sm'
          onClick={() => onConfirm(provider.id)}
        >
          Disconnect anyway
        </Button>
      </div>
    </div>
  );
}

type SignInWaysProps = {
  state: SecurityState;
  pressed: string | null;
  onConnect: (id: ProviderId) => void;
  onDisconnect: (id: ProviderId) => void;
  onConfirmDisconnect: (id: ProviderId) => void;
  onKeep: () => void;
};

export function SignInWays({
  state,
  pressed,
  onConnect,
  onDisconnect,
  onConfirmDisconnect,
  onKeep,
}: SignInWaysProps) {
  function press(provider: Provider) {
    if (provider.status === 'connected') {
      onDisconnect(provider.id);
      return;
    }
    onConnect(provider.id);
  }

  return (
    <ul
      className={cn(SURFACE, 'hairline-divide-y divide-border flex flex-col')}
    >
      {state.providers.map((provider) => {
        const statusLine = statusLineOf(provider);
        const isConfirming = state.confirmingId === provider.id;
        const pressKey = pressKeyOf(provider);

        return (
          <li key={provider.id} className='flex flex-col'>
            <div className='flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3'>
              <BrandTile brand={provider.brand} size='xl' />
              <div className='flex min-w-0 flex-1 basis-44 flex-col gap-0.5'>
                <p className='text-[13px] font-medium'>{provider.name}</p>
                <p className='text-muted-foreground flex min-w-0 text-xs'>
                  <Swap swapKey={statusLine} className='min-w-0'>
                    {statusLine}
                  </Swap>
                </p>
              </div>
              <ProviderAction
                provider={provider}
                isPressed={pressed === pressKey}
                onPress={press}
              />
            </div>
            <Fold open={isConfirming}>
              <LastWayConfirm
                provider={provider}
                pressed={pressed}
                onKeep={onKeep}
                onConfirm={onConfirmDisconnect}
              />
            </Fold>
          </li>
        );
      })}
    </ul>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  LaptopIcon,
  MonitorIcon,
  SmartphoneIcon,
  TabletIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';

import type { DeviceKind, SignedInDevice } from './data';
import { devicesWordOf } from './session';
import { SURFACE } from './settings-frame';

const DEVICE_ICON: Record<DeviceKind, Icon> = {
  laptop: LaptopIcon,
  phone: SmartphoneIcon,
  desktop: MonitorIcon,
  tablet: TabletIcon,
};

type DeviceRowProps = {
  device: SignedInDevice;
  isPressed: boolean;
  onSignOut: (id: string) => void;
};

function DeviceRow({ device, isPressed, onSignOut }: DeviceRowProps) {
  const DeviceIcon = DEVICE_ICON[device.kind];

  return (
    <div className='flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3'>
      <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
        <DeviceIcon className='size-4' />
      </span>
      <div className='flex min-w-0 flex-1 basis-44 flex-col gap-0.5'>
        <p className='flex flex-wrap items-center gap-x-2 gap-y-1 text-[13px] font-medium'>
          <span className='min-w-0'>{device.device}</span>
          {device.isThisDevice && <Badge>This device</Badge>}
        </p>
        <p className='text-muted-foreground text-xs'>
          {device.place} · {device.lastActive}
        </p>
      </div>
      {!device.isThisDevice && (
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-sign-out={device.id}
          onClick={() => onSignOut(device.id)}
          className={cn('text-muted-foreground', pressedQuietOf(isPressed))}
        >
          Sign out
        </Button>
      )}
    </div>
  );
}

type SignOutAllConfirmProps = {
  count: number;
  onCancel: () => void;
  onConfirm: () => void;
};

function SignOutAllConfirm({
  count,
  onCancel,
  onConfirm,
}: SignOutAllConfirmProps) {
  function cancelOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onCancel();
  }

  return (
    <div
      role='group'
      aria-label='Sign out of every other device'
      onKeyDown={cancelOnEscape}
      className='bg-foreground/[0.03] flex flex-wrap items-center gap-x-4 gap-y-2 px-4 py-3'
    >
      <p className='min-w-0 flex-1 basis-56 text-[13px] text-pretty'>
        <span className='font-medium'>{`Sign out of ${devicesWordOf(count)}?`}</span>{' '}
        Each one asks for a new sign-in.
      </p>
      <div className='flex gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          data-sign-out-cancel
          onClick={onCancel}
        >
          Cancel
        </Button>
        <Button
          type='button'
          variant='destructive'
          size='sm'
          onClick={onConfirm}
        >
          Sign out all
        </Button>
      </div>
    </div>
  );
}

type DeviceListProps = {
  devices: SignedInDevice[];
  otherCount: number;
  isConfirmingAll: boolean;
  pressed: string | null;
  onSignOut: (id: string) => void;
  onCancelAll: () => void;
  onConfirmAll: () => void;
};

/** A device signed out folds away; the confirm for all of them opens above the list, in place. */
export function DeviceList({
  devices,
  otherCount,
  isConfirmingAll,
  pressed,
  onSignOut,
  onCancelAll,
  onConfirmAll,
}: DeviceListProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);

  return (
    <div className={cn(SURFACE, 'overflow-hidden')}>
      <Fold open={isConfirmingAll}>
        <SignOutAllConfirm
          count={otherCount}
          onCancel={onCancelAll}
          onConfirm={onConfirmAll}
        />
      </Fold>
      <ul
        data-devices
        tabIndex={-1}
        aria-label='Signed-in devices'
        className='hairline-divide-y divide-border flex flex-col outline-none'
      >
        <AnimatePresence initial={false}>
          {devices.map((device) => (
            <motion.li
              key={device.id}
              className='overflow-hidden'
              {...presence}
            >
              <DeviceRow
                device={device}
                isPressed={pressed === `sign-out-${device.id}`}
                onSignOut={onSignOut}
              />
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
}

'use client';

import { Fragment, useId } from 'react';

import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { ShieldCheckIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { LetterTile } from '@/registry/ndeko/ui/letter-tile';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import {
  OTPField,
  OTPFieldInput,
  OTPFieldSeparator,
} from '@/registry/ndeko/ui/otp-field';
import { Switch } from '@/registry/ndeko/ui/switch';

import { CODE_LENGTH, SETUP_KEY, SETUP_KEY_TEXT, TODAY } from './data';
import {
  isTwoStepSwitchedOn,
  type SecurityState,
  type TwoStep,
} from './session';
import { describedByOf, ErrorLine, SURFACE } from './settings-frame';

const SLOTS = Array.from({ length: CODE_LENGTH }, (_, index) => index);

const SEPARATOR_AFTER = 2;

const VERIFY_LABELS: Record<MorphState, string> = {
  idle: 'Turn on',
  busy: 'Checking',
  done: 'Turned on',
};

const LINE: Record<TwoStep, string> = {
  off: 'Ask for a code from an authenticator app when you sign in on a new device',
  setup: 'Finish the two steps below to turn it on',
  verifying: 'Finish the two steps below to turn it on',
  on: `On since ${TODAY}. A new device asks for a code from your app`,
  confirmingOff: 'Still on until you confirm below',
};

function verifyStateOf(twoStep: TwoStep): MorphState {
  if (twoStep === 'verifying') {
    return 'busy';
  }
  return 'idle';
}

function slotLabelOf(index: number) {
  const position = index + 1;
  return `Digit ${position} of ${CODE_LENGTH}`;
}

function isSettingUp(twoStep: TwoStep) {
  const isSetup = twoStep === 'setup';
  const isVerifying = twoStep === 'verifying';
  return isSetup || isVerifying;
}

type SetupStepsProps = {
  state: SecurityState;
  pressed: string | null;
  onCodeChange: (code: string) => void;
  onVerify: () => void;
};

function SetupSteps({
  state,
  pressed,
  onCodeChange,
  onVerify,
}: SetupStepsProps) {
  const codeLabelId = useId();
  const errorId = useId();
  const isVerifying = state.twoStep === 'verifying';
  const hasError = state.codeError !== null;

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onVerify();
  }

  return (
    <ol className='flex flex-col gap-5 px-4 pt-1 pb-4'>
      <li className='flex gap-3'>
        <LetterTile initial='1' size='lg' />
        <div className='flex min-w-0 flex-1 flex-col gap-2'>
          <p className='text-[13px] text-pretty'>
            Add Tidewell to your authenticator app with this setup key
          </p>
          <div className='bg-foreground/[0.05] flex w-fit max-w-full items-center gap-1 rounded-lg py-1 ps-3 pe-1'>
            <code className='font-mono text-[13px] break-all'>{SETUP_KEY}</code>
            <CopyButton text={SETUP_KEY_TEXT} label='Copy the setup key' />
          </div>
        </div>
      </li>
      <li className='flex gap-3'>
        <LetterTile initial='2' size='lg' />
        <form
          noValidate
          onSubmit={submit}
          className='flex min-w-0 flex-1 flex-col gap-2'
        >
          <p id={codeLabelId} className='text-[13px] text-pretty'>
            Enter the six-digit code your app shows
          </p>
          <OTPField
            length={CODE_LENGTH}
            value={state.code}
            autoComplete='one-time-code'
            readOnly={isVerifying}
            aria-labelledby={codeLabelId}
            aria-describedby={describedByOf(hasError, errorId)}
            onValueChange={onCodeChange}
            onValueComplete={onVerify}
            className='gap-1.5'
          >
            {SLOTS.map((index) => (
              <Fragment key={index}>
                <OTPFieldInput
                  aria-label={slotLabelOf(index)}
                  aria-invalid={hasError}
                  className='size-9'
                />
                {index === SEPARATOR_AFTER && <OTPFieldSeparator />}
              </Fragment>
            ))}
          </OTPField>
          <ErrorLine
            id={errorId}
            error={state.codeError}
            attempts={state.attempts}
          />
          <div className='flex flex-wrap items-center gap-x-3 gap-y-2 pt-1'>
            <MorphButton
              type='submit'
              size='sm'
              state={verifyStateOf(state.twoStep)}
              labels={VERIFY_LABELS}
              className={pressedSolidOf(pressed === 'verify')}
            />
            <p className='text-muted-foreground text-xs'>
              This preview takes any six digits
            </p>
          </div>
        </form>
      </li>
    </ol>
  );
}

type TurnOffConfirmProps = {
  onKeep: () => void;
  onConfirm: () => void;
};

function TurnOffConfirm({ onKeep, onConfirm }: TurnOffConfirmProps) {
  function keepOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onKeep();
  }

  return (
    <div
      role='group'
      aria-label='Turn off two-step verification'
      onKeyDown={keepOnEscape}
      className='bg-warning/10 mx-4 mb-4 flex flex-col gap-3 rounded-lg p-3'
    >
      <p className='text-[13px] text-pretty'>
        <span className='font-medium'>Turn off two-step verification?</span>{' '}
        Anyone who gets into one of your sign-in accounts gets into Tidewell
        too.
      </p>
