            disabled={isVerifying}
            onCheckedChange={onSwitch}
            aria-labelledby={labelId}
            aria-describedby={lineId}
          />
        </span>
      </div>
      <Fold open={isSettingUp(twoStep)}>
        <SetupSteps
          state={state}
          pressed={pressed}
          onCodeChange={onCodeChange}
          onVerify={onVerify}
